args<-commandArgs(trailingOnly=TRUE)
source("C:/Users/dudup/OneDrive/japan-econometrics-model/src/evaluation/avaliacao_plano/common.R")
out<-args[1];check_package_protocol(readRDS(file.path(out,"config.rds")));r<-readRDS(file.path(out,"results.rds"));stopifnot(all(r$completion$complete))
labels<-c(ar="AR",naive="Passeio aleatorio",drift="Drift",var="VAR domestico (3 variaveis)",BVAR_normal_p3="BVAR normal (3)",BVAR_normal_p6="BVAR normal (6)",BVAR_condicionado_p3="BVAR condicionado (3)",BVAR_condicionado_p6="BVAR condicionado (6)",bsvarSIGNs_estavel_p3="bsvarSIGNs foreign (3), estavel",bsvarSIGNs_estavel_p6="bsvarSIGNs foreign (6), estavel")
vlabels<-c(cpi_core="CPI core",atividade="Atividade",juro_curto="Juro curto",inclinacao="Inclinacao da curva",usdjpy="USDJPY",topix="Bolsa japonesa (proxy OECD)")
md<-function(x){x<-as.data.frame(x);x[]<-lapply(x,function(z)if(is.numeric(z))ifelse(is.na(z),"NA",formatC(z,digits=3,format="f")) else as.character(z));c(paste0("| ",paste(names(x),collapse=" | ")," |"),paste0("| ",paste(rep("---",ncol(x)),collapse=" | ")," |"),apply(x,1,function(z)paste0("| ",paste(z,collapse=" | ")," |")),"")}
ref<-r$overall |> filter((variable%in%c("atividade","cpi_core")&model=="ar")|(!variable%in%c("atividade","cpi_core")&model=="naive")) |> select(variable,reference=model,ref_RMSE=RMSE,ref_CRPS=CRPS,ref_LogS=LogS)
tab<-r$overall |> left_join(ref,by="variable") |> mutate(RMSE_gain=100*(1-RMSE/ref_RMSE),CRPS_gain=100*(1-CRPS/ref_CRPS),LogS_difference=LogS-ref_LogS)
write_csv(tab,file.path(out,"comparison_reference.csv"))
best<-tab |> group_by(variable) |> slice_min(RMSE,n=1,with_ties=FALSE) |> ungroup() |> mutate(Modelo=labels[model]) |> select(variable,Modelo,RMSE,MAE,CRPS,LogS,RMSE_gain)
plotd<-tab |> filter(grepl("BVAR|bsvar",model)) |> mutate(target=vlabels[variable],Modelo=labels[model])
p<-ggplot(plotd,aes(RMSE_gain,reorder(Modelo,RMSE_gain),fill=RMSE_gain>0))+geom_col()+facet_wrap(~target,scales="free",ncol=2)+scale_fill_manual(values=c("TRUE"="#287D8E","FALSE"="#B4BCC5"),guide="none")+labs(x="Reducao do RMSE contra o benchmark (%)",y=NULL,title="Previsoes mensais: horizontes de 1 a 24 meses",subtitle="AR em atividade/CPI; passeio aleatorio nos demais alvos. Consultar diagnosticos.")+theme_minimal(base_size=11)
ggsave(file.path(out,"figures/rmse_skill.png"),p,width=12,height=10,dpi=160)
hd<-r$by_horizon |> left_join(ref |> select(variable,reference),by="variable")
href<-hd |> filter(model==reference) |> select(variable,h,ref_rmse=RMSE)
p2<-hd |> filter(grepl("BVAR|bsvar",model)) |> left_join(href,by=c("variable","h")) |> mutate(target=vlabels[variable],Modelo=labels[model]) |>
 ggplot(aes(h,RMSE/ref_rmse,color=Modelo))+geom_hline(yintercept=1,linetype=2,color="grey50")+geom_line(linewidth=.7)+facet_wrap(~target,scales="free_y",ncol=2)+scale_x_continuous(breaks=c(1,3,6,12,18,24))+labs(x="Horizonte (meses)",y="RMSE / RMSE do benchmark",color=NULL,title="Comparacao por horizonte")+theme_minimal(base_size=11)+theme(legend.position="bottom")+guides(color=guide_legend(nrow=3))
ggsave(file.path(out,"figures/rmse_horizon.png"),p2,width=12,height=10,dpi=160)
lines<-c("# Avalia\u00e7\u00e3o de forecasting \u00e0 luz do plano", "",paste0("Resultados calculados em ",format(Sys.time(),"%d/%m/%Y %H:%M %Z"),". As tr\u00eas etapas foram conclu\u00eddas; tabelas, diagn\u00f3sticos, figuras e compara\u00e7\u00e3o fiscal foram revisados."),"",
 "## Protocolo", "",
 "Previs\u00f5es mensais e reestima\u00e7\u00f5es a cada tr\u00eas meses, conforme a decis\u00e3o mais recente do usu\u00e1rio. A frequ\u00eancia das previs\u00f5es nunca foi convertida para trimestral. S\u00e3o 47 origens, com treino inicial de 180 meses e horizonte m\u00e1ximo de 24 meses. Cada modelo/alvo tem 1.028 pares origem/horizonte observados. Todas as compara\u00e7\u00f5es s\u00e3o pareadas nos mesmos casos.","",
 "Seis configura\u00e7\u00f5es foram mantidas: normal, condicionado e foreign, com 3 e 6 lags. A triagem H12 n\u00e3o produziu domin\u00e2ncia uniforme: o ranking depende do alvo e do horizonte. Por isso, ambas as defasagens continuaram candidatas.","",
 "Normal e condicionado compartilham os mesmos ajustes e estimam lambda/SOC/SUR, com psi calibrado no treino e fixo. O foreign usa lambda=0,2, mu=delta=1 e psi fixo, sem estima\u00e7\u00e3o de hiperpar\u00e2metros. Na vers\u00e3o est\u00e1vel, foram geradas 25 mil propostas e retidos 2.500 sorteios reponderados. Foi retirada apenas a normaliza\u00e7\u00e3o arbitr\u00e1ria dos sinais dos choques na estima\u00e7\u00e3o reduzida. As restri\u00e7\u00f5es foreign permanecem.","",
 "O condicionado recebe m\u00e9dias futuras do VAR externo, estimado s\u00f3 com o treino. Isso n\u00e3o equivale \u00e0 exogeneidade de bloco: o ajuste do sistema condicionado ainda permite feedback japon\u00eas para o bloco externo. A incerteza do pr\u00f3prio caminho externo n\u00e3o foi propagada.","",
 "## Menor RMSE por alvo nesta amostra", "",md(best),
 "Essa tabela identifica o menor erro observado, n\u00e3o prova superioridade estat\u00edstica. N\u00e3o se deve combinar mecanicamente as s\u00e9ries vencedoras de modelos diferentes e chamar o resultado de um sistema conjunto coerente.","",
 "![Ganho de RMSE](figures/rmse_skill.png)","", "![Desempenho por horizonte](figures/rmse_horizon.png)","",
 "## M\u00e9tricas por vari\u00e1vel", "",
 "RMSE, MAE, CRPS e LogS: menor \u00e9 melhor. LogS \u00e9 a m\u00e9dia de -log f(y), n\u00e3o log f(y). Os \u00edndices foram avaliados em 100*log e as taxas em n\u00edvel. Uma compara\u00e7\u00e3o de log scores s\u00f3 \u00e9 interpret\u00e1vel para o mesmo alvo e transforma\u00e7\u00e3o; n\u00e3o comparar diretamente magnitudes entre CPI e juros.")
for(v in alvos){
 tt<-tab |> filter(variable==v) |> arrange(RMSE) |> mutate(Modelo=labels[model]) |> select(Modelo,RMSE,MAE,CRPS,LogS,RMSE_gain,CRPS_gain,LogS_difference,coverage90)
 lines<-c(lines,"",paste0("### ",vlabels[v]),"",md(tt))
}
lines<-c(lines,"## Como as densidades foram pontuadas", "",
 "O CRPS e calculado por fabletools::CRPS(): dist_sample nos BVARs e dist_normal nos benchmarks. O log score dos BVARs usa KDE gaussiana com bandwidth bw.nrd, como scoringRules::logs_sample. O c\u00e1lculo \u00e9 feito por log-sum-exp para evitar que a densidade seja numericamente arredondada para zero nas caudas; n\u00e3o houve truncamento arbitr\u00e1rio dos scores. O c\u00e1lculo foi conferido contra scoringRules em um caso regular e testado em cauda distante. Essa KDE \u00e9 uma aproxima\u00e7\u00e3o da densidade simulada, n\u00e3o uma densidade posterior exata.","",
 "As amostras conjuntas mensais das seis vari\u00e1veis dom\u00e9sticas foram preservadas. As m\u00e9tricas apresentadas s\u00e3o marginais; n\u00e3o foi calculado um log score multivariado conjunto.","",
 "## Compara\u00e7\u00e3o dos erros: Diebold\u2013Mariano", "",
 "Os testes usam diferen\u00e7as pareadas de MSE, CRPS e LogS, separadamente por alvo e horizonte. O erro padr\u00e3o \u00e9 HAC/Newey\u2013West com pesos Bartlett, sem prewhitening. O n\u00famero de defasagens leva em conta origens a cada tr\u00eas meses: max(ceil(h/3)-1, floor(4*(n/100)^(2/9))), limitado \u00e0 amostra. H\u00e1 corre\u00e7\u00e3o de pequena amostra de Harvey\u2013Leybourne\u2013Newbold, com horizonte efetivo ceil(h/3), e refer\u00eancia t com n-1 graus de liberdade. Essa adapta\u00e7\u00e3o para origens espa\u00e7adas e para perdas dependentes deve ser interpretada como infer\u00eancia aproximada em amostra pequena.","",
 "A implementa\u00e7\u00e3o coincide com forecast::dm.test no caso verificado de horizonte 1 e lag HAC 0. Os arquivos guardam p-valores brutos e ajustados por Holm dentro de cada alvo e fun\u00e7\u00e3o de perda, considerando todos os candidatos, benchmarks e 24 horizontes. A corre\u00e7\u00e3o \u00e9 exigente; aus\u00eancia de rejei\u00e7\u00e3o n\u00e3o prova equival\u00eancia. Tamb\u00e9m h\u00e1 limita\u00e7\u00f5es na compara\u00e7\u00e3o de modelos potencialmente aninhados e na estabilidade da distribui\u00e7\u00e3o das perdas ao redor da pandemia.","",
 "Valores negativos de mean_loss_difference favorecem o candidato; p_holm abaixo de 0,05 rejeita igualdade ap\u00f3s a corre\u00e7\u00e3o. N\u00e3o foram tratados os 1.028 pares de diferentes horizontes como observa\u00e7\u00f5es independentes.","",
 "### Compara\u00e7\u00f5es com p ajustado abaixo de 0,05", "",md(r$dm_tests |> filter(p_holm<.05) |> select(variable,model,benchmark,h,loss,mean_loss_difference,p_holm)),
 "## Acerto de dire\u00e7\u00e3o e Pesaran\u2013Timmermann", "",
 "Dire\u00e7\u00e3o significa mudan\u00e7a entre o \u00faltimo valor conhecido na origem e o alvo futuro. Para o CPI, mede dire\u00e7\u00e3o do n\u00edvel de pre\u00e7os, n\u00e3o acelera\u00e7\u00e3o da infla\u00e7\u00e3o. Para o USDJPY, alta significa deprecia\u00e7\u00e3o do iene. Foram contabilizados subida, queda e zero no acerto de dire\u00e7\u00e3o. No teste bin\u00e1rio PT foram exclu\u00eddos empates, que permanecem contados no arquivo. O naive prev\u00ea mudan\u00e7a zero e, por isso, seu PT \u00e9 indefinido; isso n\u00e3o foi convertido em p-valor favor\u00e1vel.","",
 "O arquivo directions.csv apresenta PT cl\u00e1ssico e uma robustez delta/HAC para o excesso de acerto sobre a frequ\u00eancia esperada sob independ\u00eancia das propor\u00e7\u00f5es marginais. A segunda coluna n\u00e3o \u00e9 apresentada como implementa\u00e7\u00e3o do teste din\u00e2mico de Pesaran\u2013Timmermann 2009. O PT cl\u00e1ssico pressup\u00f5e condi\u00e7\u00f5es temporais que a sobreposi\u00e7\u00e3o pode violar; a robustez HAC e a amostra efetiva devem acompanhar a leitura. Os p-valores s\u00e3o unilaterais para acerto acima da independ\u00eancia e receberam Holm por alvo. Casos sem varia\u00e7\u00e3o nos sinais ou com menos de dez casos \u00fateis s\u00e3o marcados como indefinidos.","",
 "## Qualidade num\u00e9rica", "",md(r$quality),
 "Os avisos low_hyper_ess se referem \u00e0s cadeias de hiperpar\u00e2metros do BVAR; low_importance_ess e diagnostic_failure se referem \u00e0 concentra\u00e7\u00e3o dos pesos do foreign. S\u00e3o diagn\u00f3sticos diferentes. Boa m\u00e9trica n\u00e3o elimina um alerta de estima\u00e7\u00e3o. A tabela common_good.csv mant\u00e9m a mesma amostra para todos os modelos ao excluir origens com falha de diagn\u00f3stico.","",
 "## Rela\u00e7\u00e3o com o plano original", "",
 "- Preservados: dados mensais desde 2000, dez vari\u00e1veis em n\u00edveis/logs, proje\u00e7\u00f5es conjuntas mensais e avalia\u00e7\u00e3o pseudo fora da amostra desde 2015.",
 "- Alterados por decis\u00e3o/experimento: lags3/6 em vez de12; reestima\u00e7\u00e3o trimestral em vez de mensal; priors parcialmente fixos; avalia\u00e7\u00e3o com dado final revisado.",
 "- Ainda n\u00e3o implementados nesta avalia\u00e7\u00e3o: escalonamento COVID de Lenza\u2013Primiceri, identifica\u00e7\u00e3o econ\u00f4mica de sinais/narrativa, robustez p\u00f3s2013 e incerteza de caminhos externos no condicionado.",
 "- Exogeneidade estrita est\u00e1 no foreign. Condicionar previs\u00f5es em trajet\u00f3rias externas n\u00e3o imp\u00f5e os mesmos zeros nos coeficientes.",
 "- Auditoria da taxa curta: ShadowRate de Nakajima at\u00e9 fevereiro de 2024 e call rate a partir de mar\u00e7o de 2024. A conven\u00e7\u00e3o de emenda \u00e9 mensal, no in\u00edcio de mar\u00e7o.","",
 "- Auditoria do CPI: e-Stat 0003427113, categoria 0161, all items less fresh food, base 2020. O \u00edndice usado n\u00e3o \u00e9 dessazonalizado e a coleta n\u00e3o faz ajuste expl\u00edcito por imposto sobre consumo.","- Auditoria da bolsa: a coluna chamada topix vem de SPASTT01JPM661N no FRED, uma s\u00e9rie OECD de pre\u00e7os de a\u00e7\u00f5es do Jap\u00e3o. A equival\u00eancia exata com o \u00edndice TOPIX publicado pela JPX n\u00e3o foi comprovada; a base foi preservada e o alvo \u00e9 descrito como proxy de bolsa.","",
 "O plano busca tamb\u00e9m cen\u00e1rios, interpreta\u00e7\u00e3o e coer\u00eancia conjunta. O melhor forecast pontual de uma vari\u00e1vel e o melhor n\u00facleo estrutural podem ser escolhas diferentes. A recomenda\u00e7\u00e3o deve explicitar esse compromisso e manter os benchmarks como refer\u00eancias competitivas.","",
 "## Compara\u00e7\u00e3o adicional com o BoJ", "",
 "As proje\u00e7\u00f5es hist\u00f3ricas do Outlook Report s\u00e3o anuais/fiscais e foram coletadas separadamente. A avalia\u00e7\u00e3o fiscal deve usar apenas publica\u00e7\u00f5es anteriores \u00e0 origem e conceitos compat\u00edveis. Os intervalos entre membros do Board n\u00e3o s\u00e3o intervalos de previs\u00e3o: n\u00e3o se pode fabricar uma distribui\u00e7\u00e3o para calcular CRPS ou log score do BoJ. O PIB n\u00e3o pode ser comparado diretamente ao \u00edndice coincidente sem uma ponte estimada no treino. Os resultados e sua auditoria est\u00e3o na conclus\u00e3o integrada acima e no relat\u00f3rio fiscal separado.","",
 "## Arquivos", "",
 "results.rds e scores.csv preservam as tabelas; overall.csv, by_horizon.csv e by_period.csv detalham m\u00e9tricas; dm_tests.csv e directions.csv guardam testes e p-valores; diagnostics.csv, issues.csv e completion.csv documentam execu\u00e7\u00e3o e qualidade. windows/ guarda tamb\u00e9m as amostras preditivas. As amostras das quatro combinacoes de pacote/lag estao em windows/ desta nova execucao. A compara\u00e7\u00e3o H12 original/ajustada est\u00e1 em stage2_comparison_h12.csv.","",
 "## Refer\u00eancias metodol\u00f3gicas", "",
 "[scoringRules: scores de amostras](https://search.r-project.org/CRAN/refmans/scoringRules/help/logs_sample.html); [forecast: Diebold\u2013Mariano/HLN](https://robjhyndman.r-universe.dev/forecast/doc/manual.html); [implementa\u00e7\u00e3o PT no rugarch](https://github.com/alexiosg/rugarch/blob/master/R/rugarch-tests.R); [Pesaran\u2013Timmermann e depend\u00eancia serial](https://rady.ucsd.edu/_files/faculty-research/timmermann/test1.pdf); [Outlook Reports do BoJ](https://www.boj.or.jp/en/mopo/outlook/).")
